meta:
interface Meta {
  model: "gpt-4o" | "gpt-4o-mini";
  /** Sampling temperature (0-2). */
  temperature?: number;
}

namespace:
type Currency = "USD" | "EUR" | "GBP" | "JPY";

type MoneyAmount = {
  value: number;
  currency: Currency;
};

template.schema:
interface Input {
  description: string;
  amount: shared.MoneyAmount;
  category: "income" | "expense" | "transfer";
  date: string;
}

interface Output {
  summary: string;
  /** Suggested label for bookkeeping. */
  bookkeepingLabel: string;
}

interface Input {
  recentTransactions: {
    description: string;
    amount: shared.MoneyAmount;
    date: string;
  }[];
  newTransaction: {
    description: string;
    amount: shared.MoneyAmount;
    date: string;
  };
}

interface Output {
  isAnomaly: boolean;
  reason?: string;
}

namespace:
type Party = {
  name: string;
  role: "client" | "counterparty" | "witness" | "arbitrator";
  jurisdiction: string;
};

template.schema:
interface Input {
  disclosingParty: shared.Party;
  receivingParty: shared.Party;
  purposeOfDisclosure: string;
  durationYears: integer;
}

type Output = string;

interface Input {
  clauseText: string;
  /** Who is asking — affects what risks to highlight. */
  reviewingParty: shared.Party;
}

interface Output {
  plainEnglishSummary: string;
  potentialRisks: string[];
  /** Whether the clause is standard or unusual. */
  assessment: "standard" | "unusual" | "redFlag";
}
